from pathlib import Path

path = Path('lib/screens/shared/user_profile_screen.dart')
text = path.read_text(encoding='utf-8')
original = text

marker = """  Future<void> _showFinancialPaymentSheet(\n    AuthProvider auth, {\n"""
helper = """  Future<bool> _confirmFinancialPayment({\n    required BuildContext parentContext,\n    required RecordModel debt,\n    required double amount,\n  }) async {\n    final isDark = Theme.of(parentContext).brightness == Brightness.dark;\n    final remaining = debt.getDoubleValue('remaining');\n    final after = (remaining - amount).clamp(0.0, remaining).toDouble();\n    final currency = debt.getStringValue('currency').trim().isEmpty\n        ? 'IQD'\n        : debt.getStringValue('currency');\n    final description = debt.getStringValue('description').trim();\n\n    final result = await showDialog<bool>(\n      context: parentContext,\n      builder: (dialogContext) => AlertDialog(\n        title: const Row(\n          children: [\n            Icon(Icons.verified_outlined, color: Colors.green),\n            SizedBox(width: 8),\n            Text('پشتڕاستکردنەوەی پارەدان'),\n          ],\n        ),\n        content: Column(\n          mainAxisSize: MainAxisSize.min,\n          crossAxisAlignment: CrossAxisAlignment.stretch,\n          children: [\n            if (description.isNotEmpty) ...[\n              Text(\n                description,\n                maxLines: 2,\n                overflow: TextOverflow.ellipsis,\n                style: const TextStyle(fontWeight: FontWeight.w700),\n              ),\n              const SizedBox(height: 12),\n            ],\n            _buildPaymentConfirmationRow(\n              'ماوەی پێش پارەدان',\n              AppHelpers.formatCurrencyWithType(remaining, currency),\n              isDark,\n            ),\n            const SizedBox(height: 8),\n            _buildPaymentConfirmationRow(\n              'بڕی پارەدان',\n              AppHelpers.formatCurrencyWithType(amount, currency),\n              isDark,\n              valueColor: Colors.green.shade700,\n            ),\n            const Divider(height: 20),\n            _buildPaymentConfirmationRow(\n              'ماوەی دوای پارەدان',\n              AppHelpers.formatCurrencyWithType(after, currency),\n              isDark,\n              valueColor: after > 0 ? Colors.orange.shade800 : Colors.green.shade700,\n              emphasized: true,\n            ),\n            if (after <= 0) ...[\n              const SizedBox(height: 10),\n              Container(\n                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),\n                decoration: BoxDecoration(\n                  color: Colors.green.withValues(alpha: 0.08),\n                  borderRadius: BorderRadius.circular(10),\n                ),\n                child: const Row(\n                  children: [\n                    Icon(Icons.done_all_rounded, color: Colors.green, size: 18),\n                    SizedBox(width: 7),\n                    Expanded(\n                      child: Text(\n                        'ئەم پارەدانە قەرزەکە بە تەواوی دادەخات.',\n                        style: TextStyle(\n                          color: Colors.green,\n                          fontSize: 11.5,\n                          fontWeight: FontWeight.w700,\n                        ),\n                      ),\n                    ),\n                  ],\n                ),\n              ),\n            ],\n          ],\n        ),\n        actions: [\n          TextButton(\n            onPressed: () => Navigator.pop(dialogContext, false),\n            child: const Text('پاشگەزبوونەوە'),\n          ),\n          FilledButton.icon(\n            onPressed: () => Navigator.pop(dialogContext, true),\n            icon: const Icon(Icons.check_rounded, size: 18),\n            label: const Text('پشتڕاستە — تۆمار بکە'),\n            style: FilledButton.styleFrom(\n              backgroundColor: Colors.green.shade700,\n            ),\n          ),\n        ],\n      ),\n    );\n    return result == true;\n  }\n\n  Widget _buildPaymentConfirmationRow(\n    String label,\n    String value,\n    bool isDark, {\n    Color? valueColor,\n    bool emphasized = false,\n  }) {\n    return Row(\n      children: [\n        Expanded(\n          child: Text(\n            label,\n            style: TextStyle(\n              fontSize: emphasized ? 12.5 : 11.5,\n              fontWeight: emphasized ? FontWeight.w800 : FontWeight.w600,\n              color: isDark\n                  ? AppDarkColors.textSecondary\n                  : const Color(0xFF667085),\n            ),\n          ),\n        ),\n        const SizedBox(width: 10),\n        Text(\n          value,\n          textDirection: TextDirection.ltr,\n          style: TextStyle(\n            fontSize: emphasized ? 14 : 12.5,\n            fontWeight: FontWeight.w900,\n            color: valueColor ??\n                (isDark ? AppDarkColors.textPrimary : const Color(0xFF1D2939)),\n          ),\n        ),\n      ],\n    );\n  }\n\n"""
assert marker in text, 'payment sheet marker missing'
text = text.replace(marker, helper + marker, 1)

old = """                                setSheetState(() {\n                                  saving = true;\n                                  localError = null;\n                                });\n                                try {\n                                  await PBService.createPayment(\n"""
new = """                                final confirmed = await _confirmFinancialPayment(\n                                  parentContext: sheetContext,\n                                  debt: selectedDebt,\n                                  amount: amount,\n                                );\n                                if (!confirmed || !sheetContext.mounted) return;\n\n                                setSheetState(() {\n                                  saving = true;\n                                  localError = null;\n                                });\n                                try {\n                                  await PBService.createPayment(\n"""
assert old in text, 'payment submit marker missing'
text = text.replace(old, new, 1)

assert text != original
path.write_text(text, encoding='utf-8')
print('Payment confirmation applied')
